-- Keep the malformed predicates in sync with the strict timestamp decoder.
CREATE INDEX IF NOT EXISTS idx_tool_policy_malformed ON tool_policy(namespace, actor, tool)
WHERE (typeof(created_at) NOT IN ('integer', 'real') OR (typeof(created_at) = 'real' AND (created_at < -9223372036854775808.0 OR created_at >= 9223372036854775808.0 OR created_at != CAST(created_at AS INTEGER)))) OR (typeof(updated_at) NOT IN ('integer', 'real', 'null') OR (typeof(updated_at) = 'real' AND (updated_at < -9223372036854775808.0 OR updated_at >= 9223372036854775808.0 OR updated_at != CAST(updated_at AS INTEGER)))) OR (typeof(deleted_at) NOT IN ('integer', 'real', 'null') OR (typeof(deleted_at) = 'real' AND (deleted_at < -9223372036854775808.0 OR deleted_at >= 9223372036854775808.0 OR deleted_at != CAST(deleted_at AS INTEGER))));

CREATE INDEX IF NOT EXISTS idx_tool_grants_malformed ON tool_grants(namespace, actor, tool)
WHERE (typeof(requested_at) NOT IN ('integer', 'real') OR (typeof(requested_at) = 'real' AND (requested_at < -9223372036854775808.0 OR requested_at >= 9223372036854775808.0 OR requested_at != CAST(requested_at AS INTEGER)))) OR (typeof(decided_at) NOT IN ('integer', 'real', 'null') OR (typeof(decided_at) = 'real' AND (decided_at < -9223372036854775808.0 OR decided_at >= 9223372036854775808.0 OR decided_at != CAST(decided_at AS INTEGER)))) OR (typeof(expires_at) NOT IN ('integer', 'real', 'null') OR (typeof(expires_at) = 'real' AND (expires_at < -9223372036854775808.0 OR expires_at >= 9223372036854775808.0 OR expires_at != CAST(expires_at AS INTEGER)))) OR (typeof(invalidated_at) NOT IN ('integer', 'real', 'null') OR (typeof(invalidated_at) = 'real' AND (invalidated_at < -9223372036854775808.0 OR invalidated_at >= 9223372036854775808.0 OR invalidated_at != CAST(invalidated_at AS INTEGER))));

CREATE INDEX IF NOT EXISTS idx_tool_grants_live ON tool_grants(namespace, status, requested_at DESC, id, actor, tool)
WHERE status = 'granted' AND invalidated_by_registry_id IS NULL AND invalidated_at IS NULL;
